python3 -c "
results = {}
N_MAX = 2000

for a in range(1, N_MAX):
    for b in range(a+1, N_MAX):
        n = a**3 + b**3
        if n > N_MAX**3:
            break
        if n in results:
            results[n].append((a, b))
        else:
            results[n] = [(a, b)]

# Find smallest N expressible as sum of two positive cubes in 2+ different ways
multi = {n: pairs for n, pairs in results.items() if len(pairs) >= 2}
if multi:
    smallest = min(multi.keys())
    print(f'Smallest: {smallest}')
    print(f'Representations: {multi[smallest]}')
    cbrt = round(smallest**(1/3))
    print(f'Cube root check: {cbrt}^3 = {cbrt**3}')

# Also check if any perfect cube qualifies
print('\\nChecking if any perfect cube works:')
found_cube = False
for n, pairs in sorted(multi.items()):
    cr = round(n**(1/3))
    for c in [cr-1, cr, cr+1]:
        if c > 0 and c**3 == n:
            print(f'Found: {n} = {c}^3, pairs: {pairs}')
            found_cube = True
            break
if not found_cube:
    print('None found (consistent with Fermats Last Theorem - Euler 1770)')
"
